-- ============================================================================
-- BHA location hierarchy seed: Namibia (NA)
-- Source: "Africa Location Hierarchies - Universal Review" - Namibia
-- 1048 locations beyond the country root. Idempotent: re-running refreshes.
-- Prerequisite: supabase/migrations/004_location_hierarchy.sql
-- ============================================================================

-- 0. Country row (adds any territory missing from the base schema seed)
insert into public.countries (code, name) values
  ('NA', 'Namibia')
on conflict (code) do update set name = excluded.name;

-- 1. Country root (level 1)
insert into public.locations (country_code, parent_id, name, location_type, level, path, sort_order)
select 'NA', null, 'Namibia', 'Country', 1, 'namibia', 0
on conflict (country_code, path) do update set
  name = excluded.name, location_type = excluded.location_type, level = excluded.level;

-- 2. Level 2 (14 rows)
insert into public.locations (country_code, parent_id, name, location_type, level, path, sort_order)
select 'NA', p.id, v.name, v.location_type, v.level, v.path, v.sort_order
from (values
    ('namibia', 'Erongo Region', 'Region', 2, 'namibia/erongo-region', 0),
    ('namibia', 'Hardap Region', 'Region', 2, 'namibia/hardap-region', 1),
    ('namibia', 'Kavango East Region', 'Region', 2, 'namibia/kavango-east-region', 2),
    ('namibia', 'Kavango West Region', 'Region', 2, 'namibia/kavango-west-region', 3),
    ('namibia', 'Khomas Region', 'Region', 2, 'namibia/khomas-region', 4),
    ('namibia', 'Kunene Region', 'Region', 2, 'namibia/kunene-region', 5),
    ('namibia', 'Ohangwena Region', 'Region', 2, 'namibia/ohangwena-region', 6),
    ('namibia', 'Omaheke Region', 'Region', 2, 'namibia/omaheke-region', 7),
    ('namibia', 'Omusati Region', 'Region', 2, 'namibia/omusati-region', 8),
    ('namibia', 'Oshana Region', 'Region', 2, 'namibia/oshana-region', 9),
    ('namibia', 'Oshikoto Region', 'Region', 2, 'namibia/oshikoto-region', 10),
    ('namibia', 'Otjozondjupa Region', 'Region', 2, 'namibia/otjozondjupa-region', 11),
    ('namibia', 'Zambezi Region', 'Region', 2, 'namibia/zambezi-region', 12),
    ('namibia', 'ǁKaras Region', 'Region', 2, 'namibia/karas-region', 13)
) as v(parent_path, name, location_type, level, path, sort_order)
join public.locations p
  on p.country_code = 'NA' and p.path = v.parent_path
on conflict (country_code, path) do update set
  name = excluded.name, location_type = excluded.location_type, level = excluded.level,
  sort_order = excluded.sort_order, parent_id = excluded.parent_id;

